/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS certificate paths are read exclusively from environment variables so that
 * no secrets or file-system paths are ever hard-coded:
 *
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be set and the files must be readable for HTTPS to be
 * enabled.  If either variable is absent the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   The cert/key buffers when both files are present and readable,
 *   or `null` when TLS should not be enabled.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be provided.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Verify both files exist and are readable before attempting to load them.
  try {
    fs.accessSync(resolvedCert, fs.constants.R_OK);
    fs.accessSync(resolvedKey,  fs.constants.R_OK);
  } catch (err) {
    console.warn(
      '[config] TLS certificate files could not be read – falling back to ' +
      `HTTP-only. (${err.message})`
    );
    return null;
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(
      '[config] Failed to load TLS credentials – falling back to ' +
      `HTTP-only. (${err.message})`
    );
    return null;
  }
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  /**
   * TLS credentials object `{ cert, key }` when both environment variables are
   * set and the files are readable; `null` otherwise.
   */
  tlsCredentials: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • Always starts an HTTP server on HTTP_PORT  (default 3000).
 *  • When TLS_CERT_PATH and TLS_KEY_PATH environment variables point to valid,
 *    readable PEM files an HTTPS server is also started on HTTPS_PORT
 *    (default 3443).
 *  • When the certificate files are absent or unreadable the process falls back
 *    to HTTP-only and logs a warning – it does NOT crash.
 *
 * Environment variables (see config.js for full details)
 * ──────────────────────────────────────────────────────
 *  TLS_CERT_PATH   Path to PEM certificate file   (enables HTTPS when set)
 *  TLS_KEY_PATH    Path to PEM private-key file   (enables HTTPS when set)
 *  HTTP_PORT       Override HTTP  port             (default: 3000)
 *  HTTPS_PORT      Override HTTPS port             (default: 3443)
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, tlsCredentials } = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup (only when run directly, not when required by tests) ───────

if (require.main === module) {
  startServers();
}

/**
 * Start HTTP and, when TLS credentials are available, HTTPS servers.
 *
 * Exported so that integration tests can call it with a controlled config if
 * needed.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // ── HTTP ──────────────────────────────────────────────────────────────────
  const httpServer = http.createServer(app);

  httpServer.listen(HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
  });

  httpServer.on('error', (err) => {
    console.error(`[http]  Server error: ${err.message}`);
  });

  // ── HTTPS (conditional) ───────────────────────────────────────────────────
  let httpsServer = null;

  if (tlsCredentials) {
    httpsServer = https.createServer(
      {
        cert: tlsCredentials.cert,
        key:  tlsCredentials.key,
      },
      app
    );

    httpsServer.listen(HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
    });

    httpsServer.on('error', (err) => {
      console.error(`[https] Server error: ${err.message}`);
    });
  } else {
    console.warn(
      '[https] TLS credentials not available – running HTTP-only. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return { httpServer, httpsServer };
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = app;           // Express app (for supertest / unit tests)
module.exports.startServers = startServers;

