'use strict';
// ── helpers ──────────────────────────────────────────────────────────────────
let passed = 0, failed = 0;
function assert(label, condition, detail = '') {
  if (condition) {
    console.log('  PASS:', label);
    passed++;
  } else {
    console.error('  FAIL:', label, detail ? '– ' + detail : '');
    failed++;
  }
}

// ── 1. config – no env vars → tlsCredentials is null ─────────────────────────
console.log('\n[1] config: no TLS env vars');
delete process.env.TLS_CERT_PATH;
delete process.env.TLS_KEY_PATH;
// bust require cache so env is re-read
delete require.cache[require.resolve('./config')];
const cfg1 = require('./config');
assert('tlsCredentials is null',  cfg1.tlsCredentials === null);
assert('HTTP_PORT  defaults 3000', cfg1.HTTP_PORT  === 3000);
assert('HTTPS_PORT defaults 3443', cfg1.HTTPS_PORT === 3443);

// ── 2. config – env vars set but files do not exist → null + warning ──────────
console.log('\n[2] config: env vars point to non-existent files');
process.env.TLS_CERT_PATH = '/tmp/does-not-exist.crt';
process.env.TLS_KEY_PATH  = '/tmp/does-not-exist.key';
delete require.cache[require.resolve('./config')];
const cfg2 = require('./config');
assert('tlsCredentials is null (missing files)', cfg2.tlsCredentials === null);

// ── 3. config – valid files → credentials loaded ─────────────────────────────
console.log('\n[3] config: valid cert/key files');
// Write tiny placeholder PEM-like files (content validity is checked by https,
// not by config.js – config only checks readability).
const fs   = require('fs');
const path = require('path');
const CERT = path.join('/tmp', 'test.crt');
const KEY  = path.join('/tmp', 'test.key');
fs.writeFileSync(CERT, 'CERT_PLACEHOLDER');
fs.writeFileSync(KEY,  'KEY_PLACEHOLDER');
process.env.TLS_CERT_PATH = CERT;
process.env.TLS_KEY_PATH  = KEY;
delete require.cache[require.resolve('./config')];
const cfg3 = require('./config');
assert('tlsCredentials is not null',               cfg3.tlsCredentials !== null);
assert('tlsCredentials.cert is a Buffer',          Buffer.isBuffer(cfg3.tlsCredentials.cert));
assert('tlsCredentials.key  is a Buffer',          Buffer.isBuffer(cfg3.tlsCredentials.key));
assert('cert content matches written file',        cfg3.tlsCredentials.cert.toString() === 'CERT_PLACEHOLDER');
assert('key  content matches written file',        cfg3.tlsCredentials.key.toString()  === 'KEY_PLACEHOLDER');

// ── 4. config – custom port env vars ─────────────────────────────────────────
console.log('\n[4] config: custom port env vars');
process.env.HTTP_PORT  = '4000';
process.env.HTTPS_PORT = '4443';
delete require.cache[require.resolve('./config')];
const cfg4 = require('./config');
assert('HTTP_PORT  = 4000', cfg4.HTTP_PORT  === 4000);
assert('HTTPS_PORT = 4443', cfg4.HTTPS_PORT === 4443);
// reset
delete process.env.HTTP_PORT;
delete process.env.HTTPS_PORT;

// ── 5. app – module.exports is an Express app ─────────────────────────────────
console.log('\n[5] app: module.exports is an Express app');
delete process.env.TLS_CERT_PATH;
delete process.env.TLS_KEY_PATH;
delete require.cache[require.resolve('./config')];
delete require.cache[require.resolve('./app')];
const app = require('./app');
assert('app is a function',              typeof app === 'function');
assert('startServers is exported',       typeof app.startServers === 'function');

// ── 6. app – HTTP-only startServers (no TLS env vars) ────────────────────────
console.log('\n[6] app: startServers – HTTP-only mode');
const { httpServer: s6http, httpsServer: s6https } = app.startServers();
assert('httpServer  is not null',  s6http  !== null);
assert('httpsServer is null',      s6https === null);
s6http.close();

// ── 7. app – startServers – HTTPS mode using a real self-signed cert ──────────
console.log('\n[7] app: startServers – HTTPS mode with real self-signed cert');
// Generate a temporary self-signed cert via openssl
const { execSync } = require('child_process');
try {
  execSync(
    'openssl req -x509 -newkey rsa:2048 -keyout /tmp/srv.key -out /tmp/srv.crt ' +
    '-days 1 -nodes -subj \"/CN=localhost\" 2>/dev/null'
  );
  process.env.TLS_CERT_PATH = '/tmp/srv.crt';
  process.env.TLS_KEY_PATH  = '/tmp/srv.key';
  delete require.cache[require.resolve('./config')];
  delete require.cache[require.resolve('./app')];
  const app2 = require('./app');
  const { httpServer: s7http, httpsServer: s7https } = app2.startServers();
  assert('httpServer  is not null',         s7http  !== null);
  assert('httpsServer is not null',         s7https !== null);
  assert('httpsServer is https.Server',
         s7https && s7https.constructor && s7https.constructor.name === 'Server');
  // Verify HTTPS server is actually listening
  const waitListen = (srv) => new Promise(res => {
    if (srv.listening) return res();
    srv.once('listening', res);
  });
  Promise.all([waitListen(s7http), waitListen(s7https)]).then(() => {
    assert('HTTP  server is listening',  s7http.listening);
    assert('HTTPS server is listening',  s7https.listening);
    s7http.close();
    s7https.close();
    summary();
  });
} catch (e) {
  console.warn('  SKIP: openssl not available –', e.message);
  summary();
}

function summary() {
  console.log('\n──────────────────────────────────────────');
  console.log('Results:', passed, 'passed,', failed, 'failed');
  if (failed > 0) process.exit(1);
}
