/**
 * config.js
 *
 * Central configuration module.
 * TLS certificate paths are read exclusively from environment variables so
 * that no secrets or file-system paths are ever hard-coded.
 *
 * Environment variables
 * ---------------------
 * TLS_CERT_PATH  – Absolute (or relative) path to the PEM-encoded TLS certificate file.
 * TLS_KEY_PATH   – Absolute (or relative) path to the PEM-encoded private-key file.
 *
 * When either variable is absent the `tls` property is null, which signals
 * app.js to skip HTTPS and run HTTP-only.
 */

'use strict';

const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  ?? '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT ?? '3443', 10);

// ── TLS ──────────────────────────────────────────────────────────────────────

/**
 * Resolve a raw path string from an environment variable.
 * Returns null when the variable is unset or contains only whitespace.
 *
 * @param {string} envVar - Name of the environment variable to read.
 * @returns {string|null}
 */
function resolveEnvPath(envVar) {
  const raw = process.env[envVar];
  if (!raw || !raw.trim()) return null;
  // Resolve relative paths against the working directory at startup time so
  // behaviour is consistent regardless of where the module is required from.
  return path.resolve(raw.trim());
}

const certPath = resolveEnvPath('TLS_CERT_PATH');
const keyPath  = resolveEnvPath('TLS_KEY_PATH');

/**
 * TLS file paths, or null when certs are not configured.
 *
 * Both variables must be present; a half-configured pair is treated as
 * absent (the server will log a warning and fall back to HTTP-only).
 *
 * @type {{ certPath: string, keyPath: string }|null}
 */
const tls = (certPath && keyPath) ? { certPath, keyPath } : null;

if ((certPath && !keyPath) || (!certPath && keyPath)) {
  console.warn(
    '[config] Warning: only one of TLS_CERT_PATH / TLS_KEY_PATH is set. ' +
    'Both are required to enable HTTPS. Falling back to HTTP-only.'
  );
}

// ── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  tls,
};

'use strict';

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Start-up behaviour
 * ──────────────────
 * • Always binds an HTTP server on HTTP_PORT (default 3000).
 * • When TLS_CERT_PATH and TLS_KEY_PATH are both set in the environment,
 *   also binds an HTTPS server on HTTPS_PORT (default 3443).
 * • If either cert path is missing, HTTPS is skipped with a clear log message.
 * • If the cert/key files cannot be read at start-up, the process exits with a
 *   non-zero code so the issue is caught immediately rather than silently
 *   serving HTTP-only without the operator's knowledge.
 */

const fs      = require('fs');
const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, tls } = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server helpers ────────────────────────────────────────────────────────────

/**
 * Load TLS credentials from disk.
 *
 * Exits the process when the files cannot be read so that a misconfigured
 * deployment fails loudly instead of silently degrading to HTTP-only.
 *
 * @param {{ certPath: string, keyPath: string }} tlsConfig
 * @returns {{ cert: Buffer, key: Buffer }}
 */
function loadTlsCredentials(tlsConfig) {
  try {
    return {
      cert: fs.readFileSync(tlsConfig.certPath),
      key:  fs.readFileSync(tlsConfig.keyPath),
    };
  } catch (err) {
    console.error(
      `[app] Fatal: could not read TLS files – ${err.message}\n` +
      '      Check that TLS_CERT_PATH and TLS_KEY_PATH point to readable files.'
    );
    process.exit(1);
  }
}

/**
 * Start a server and log the result.
 *
 * @param {http.Server|https.Server} server
 * @param {number} port
 * @param {string} protocol - 'HTTP' or 'HTTPS'
 */
function startServer(server, port, protocol) {
  server.listen(port, () => {
    console.log(`[app] ${protocol} server listening on port ${port}`);
  });

  server.on('error', (err) => {
    console.error(`[app] ${protocol} server error on port ${port}: ${err.message}`);
    // A fatal bind error on the HTTPS port should not silently keep HTTP running
    // under the operator's assumption that HTTPS is active.
    process.exit(1);
  });
}

// ── Start servers ─────────────────────────────────────────────────────────────

// HTTP — always started.
const httpServer = http.createServer(app);
startServer(httpServer, HTTP_PORT, 'HTTP');

// HTTPS — only when cert paths are fully configured.
if (tls) {
  const credentials = loadTlsCredentials(tls);
  const httpsServer = https.createServer(credentials, app);
  startServer(httpsServer, HTTPS_PORT, 'HTTPS');
} else {
  console.log(
    '[app] TLS_CERT_PATH / TLS_KEY_PATH not configured – running HTTP-only.'
  );
}

module.exports = app;

