/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour
 * ─────────────
 * Set the following environment variables to enable HTTPS:
 *
 *   TLS_CERT_PATH   Absolute (or relative) path to the PEM-encoded certificate
 *                   file (or full chain), e.g. /etc/tls/server.crt
 *
 *   TLS_KEY_PATH    Absolute (or relative) path to the PEM-encoded private-key
 *                   file that matches the certificate, e.g. /etc/tls/server.key
 *
 * When both variables are set the module attempts to read the files.  If either
 * variable is missing, or a file cannot be read, `tls` is returned as `null`
 * and the caller should fall back to HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ──────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths declared in the environment.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   Credential buffers on success, or `null` when HTTPS should not be started.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be provided.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a clear warning so operators know why HTTPS did not start.
    console.warn(
      `[config] HTTPS disabled — could not read TLS file: ${err.message}`
    );
    return null;
  }
}

// ── Exports ────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * TLS credentials object `{ cert, key }` when both paths are set and the
   * files are readable; `null` otherwise.
   */
  tls: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Start-up behaviour
 * ──────────────────
 *  • HTTP  is always started on HTTP_PORT  (default 3000).
 *  • HTTPS is started on HTTPS_PORT (default 3443) only when TLS_CERT_PATH
 *    and TLS_KEY_PATH are set and their files are readable (see config.js).
 *  • When TLS files are unavailable the server falls back to HTTP-only and
 *    logs a clear message explaining why.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ── Express application ────────────────────────────────────────────────────

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ─────────────────────────────────────────────────────────

/**
 * Start the HTTP server (always).
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server: ${err.message}`);
  });

  return server;
}

/**
 * Start the HTTPS server when TLS credentials are available.
 *
 * @returns {https.Server | null} The HTTPS server instance, or null when
 *   credentials are not available.
 */
function startHttps() {
  if (!config.tls) {
    console.warn(
      '[https] TLS credentials not available — ' +
      'set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS. ' +
      'Running in HTTP-only mode.'
    );
    return null;
  }

  const server = https.createServer(
    { cert: config.tls.cert, key: config.tls.key },
    app
  );

  server.listen(config.HTTPS_PORT, () => {
    console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[https] Failed to start HTTPS server: ${err.message}`);
  });

  return server;
}

// Only start servers when this file is executed directly (not when required
// by tests or other modules).
if (require.main === module) {
  startHttp();
  startHttps();
}

// ── Exports ────────────────────────────────────────────────────────────────

module.exports = { app, startHttp, startHttps };

