/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven by two environment variables:
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is absent the application starts in HTTP-only
 * mode without throwing an error.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   The raw file buffers when both files are present and readable,
 *   or `null` when TLS should not be enabled.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be provided.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Verify the files exist and are readable before trying to load them.
  try {
    fs.accessSync(resolvedCert, fs.constants.R_OK);
    fs.accessSync(resolvedKey,  fs.constants.R_OK);
  } catch (err) {
    console.warn(
      '[config] TLS certificate or key file is not readable – ' +
      'falling back to HTTP only.\n  Detail: %s',
      err.message,
    );
    return null;
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(
      '[config] Failed to read TLS files – falling back to HTTP only.\n' +
      '  Detail: %s',
      err.message,
    );
    return null;
  }
}

// Evaluate once at startup so the rest of the application gets a stable object.
const tlsCredentials = loadTlsCredentials();

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /** `true` when valid TLS credentials were loaded successfully. */
  TLS_ENABLED: tlsCredentials !== null,

  /**
   * TLS options object suitable for passing directly to `https.createServer()`,
   * or `null` when TLS is not available.
   *
   * @type {{ cert: Buffer, key: Buffer } | null}
   */
  tlsCredentials,
};

