  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start the HTTP server unconditionally.
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server: ${err.message}`);
    process.exit(1);
  });

  return server;
}

/**
 * Start the HTTPS server when TLS credentials are available.
