# ── 1. Syntax / require-resolution check (no env vars set → HTTP-only path) ──
node --check config.js && echo "config.js syntax OK"
node --check app.js    && echo "app.js syntax OK"

# ── 2. Confirm config loads cleanly with no env vars (TLS_ENABLED must be false) ──
node -e "
const c = require('./config');
console.assert(c.TLS_ENABLED   === false, 'TLS_ENABLED should be false');
console.assert(c.tlsCredentials === null,  'tlsCredentials should be null');
console.assert(c.HTTP_PORT      === 3000,  'HTTP_PORT should be 3000');
console.assert(c.HTTPS_PORT     === 3443,  'HTTPS_PORT should be 3443');
console.log('config defaults: OK');
"

# ── 3. Confirm port overrides work ──
node -e "
process.env.HTTP_PORT  = '4000';
process.env.HTTPS_PORT = '4443';
// Clear require cache so the new env is picked up
delete require.cache[require.resolve('./config')];
const c = require('./config');
console.assert(c.HTTP_PORT  === 4000, 'HTTP_PORT override failed');
console.assert(c.HTTPS_PORT === 4443, 'HTTPS_PORT override failed');
console.log('config port overrides: OK');
"

# ── 4. Confirm TLS_ENABLED=true when real (self-signed) certs are provided ──
# Generate a temporary self-signed cert pair
TMPDIR=$(mktemp -d)
openssl req -x509 -newkey rsa:2048 -keyout "$TMPDIR/key.pem" \
            -out "$TMPDIR/cert.pem" -days 1 -nodes \
            -subj "/CN=localhost" 2>/dev/null
node -e "
