console.assert(c.TLS_ENABLED            === true,   'TLS_ENABLED should be true');
console.assert(c.tlsCredentials         !== null,   'tlsCredentials should not be null');
console.assert(Buffer.isBuffer(c.tlsCredentials.cert), 'cert should be a Buffer');
console.assert(Buffer.isBuffer(c.tlsCredentials.key),  'key should be a Buffer');
console.log('config TLS credential loading: OK');
"

# ── 5. Confirm TLS falls back gracefully when paths point to missing files ──
node -e "
