console.assert(c.tlsCredentials === null,  'tlsCredentials should be null for missing files');
console.log('config fallback on missing files: OK');
" 2>&1   # stderr will include the expected [config] warning – that is correct

# ── 6. Module-level require of app.js must not start listeners ──
node -e "
