function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    console.warn(
      '[config] TLS_CERT_PATH and/or TLS_KEY_PATH are not set. ' +
      'HTTPS will be disabled.'
    );
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Verify that the files actually exist before trying to read them so that
  // the error message is clear and actionable.
  for (const [label, filePath] of [['certificate', resolvedCert], ['key', resolvedKey]]) {
    if (!fs.existsSync(filePath)) {
      console.error(
