      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.error(`[config] Failed to read TLS files: ${err.message}. HTTPS will be disabled.`);
    return null;
  }
}

