/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS certificate paths are read exclusively from the environment variables
 * TLS_CERT_PATH and TLS_KEY_PATH.  Both must be set (and the files must be
 * readable) for HTTPS to be enabled; otherwise the server falls back to
 * HTTP-only mode.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS helpers
// ---------------------------------------------------------------------------

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   The raw certificate/key buffers when both paths are configured and
 *   readable, or `null` when HTTPS should be skipped.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    console.warn(
      '[config] TLS_CERT_PATH and/or TLS_KEY_PATH are not set — ' +
      'HTTPS will be disabled.'
    );
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Validate that both files exist and are readable before returning them.
  try {
    fs.accessSync(resolvedCert, fs.constants.R_OK);
  } catch {
    console.error(
      `[config] TLS certificate file is not readable: ${resolvedCert} — ` +
      'HTTPS will be disabled.'
    );
    return null;
  }

  try {
    fs.accessSync(resolvedKey, fs.constants.R_OK);
  } catch {
    console.error(
      `[config] TLS key file is not readable: ${resolvedKey} — ` +
      'HTTPS will be disabled.'
    );
    return null;
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.error(
      `[config] Failed to read TLS files: ${err.message} — ` +
      'HTTPS will be disabled.'
    );
    return null;
  }
}

// ---------------------------------------------------------------------------
// Exported configuration
// ---------------------------------------------------------------------------
const tlsCredentials = loadTlsCredentials();

module.exports = {
  /** TCP port for the plain-HTTP server. */
  HTTP_PORT,

  /** TCP port for the HTTPS server (only used when TLS is available). */
  HTTPS_PORT,

  /**
   * TLS credentials object `{ cert, key }` when both environment variables
   * are set and the files are readable; `null` otherwise.
   */
  tlsCredentials,

  /** Convenience boolean — `true` when HTTPS will be started. */
  get httpsEnabled() {
    return tlsCredentials !== null;
  },
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • Always starts an HTTP server on HTTP_PORT (default 3000).
 *  • When TLS_CERT_PATH and TLS_KEY_PATH resolve to readable files, also
 *    starts an HTTPS server on HTTPS_PORT (default 3443).
 *  • Falls back to HTTP-only with a console warning when certs are absent or
 *    unreadable.  No exception is thrown — the process stays alive.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup — only runs when this file is executed directly so that test
// suites that `require('./app')` do not accidentally bind ports.
// ---------------------------------------------------------------------------
if (require.main === module) {
  // -- HTTP (always) --------------------------------------------------------
  const httpServer = http.createServer(app);

  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening  →  http://localhost:${config.HTTP_PORT}`);
  });

  httpServer.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server: ${err.message}`);
    process.exit(1);
  });

  // -- HTTPS (when certs are available) -------------------------------------
  if (config.httpsEnabled) {
    const httpsServer = https.createServer(config.tlsCredentials, app);

    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening  →  https://localhost:${config.HTTPS_PORT}`);
    });

    httpsServer.on('error', (err) => {
      // A failure here is non-fatal — HTTP is still running.
      console.error(
        `[https] Failed to start HTTPS server: ${err.message} — ` +
        'continuing with HTTP only.'
      );
    });
  } else {
    console.warn('[https] HTTPS is disabled — running in HTTP-only mode.');
  }
}

module.exports = app;

