  const server = http.createServer(app);

  server.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Server error: ${err.message}`);
  });

  return server;
}

/**
 * Start the HTTPS server on HTTPS_PORT (default 3443) using the TLS
 * credentials supplied via TLS_CERT_PATH / TLS_KEY_PATH environment variables.
 *
 * Only called when config.tlsEnabled is true.
 */
function startHttpsServer() {
  const server = https.createServer(config.tlsCredentials, app);

  server.listen(config.HTTPS_PORT, () => {
    console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[https] Server error: ${err.message}`);
  });

  return server;
