/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM-encoded certificate file
 *   TLS_KEY_PATH   – absolute or relative path to the PEM-encoded private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is missing the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── ports ─────────────────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   Returns an object with the raw file buffers when both paths are configured
 *   and the files can be read, otherwise returns null.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a clear warning so operators know why HTTPS did not start.
    console.warn(
      `[config] HTTPS disabled – could not read TLS files: ${err.message}`
    );
    return null;
  }
}

const tlsCredentials = loadTlsCredentials();
const tlsEnabled     = tlsCredentials !== null;

// ── exports ───────────────────────────────────────────────────────────────────
module.exports = {
  /** Port for the plain-HTTP server (default 3000). */
  HTTP_PORT,

  /** Port for the HTTPS server (default 3443). Only used when tlsEnabled is true. */
  HTTPS_PORT,

  /**
   * True when both TLS_CERT_PATH and TLS_KEY_PATH are set and the files were
   * read successfully.
   */
  tlsEnabled,

  /**
   * TLS credentials object ({ cert, key }) ready to be passed directly to
   * `https.createServer()`, or null when TLS is unavailable.
   */
  tlsCredentials,
};

