/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is controlled exclusively by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM-encoded certificate
 *   TLS_KEY_PATH   – absolute or relative path to the PEM-encoded private key
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either is missing the server falls back to HTTP-only mode and
 * logs a clear warning so the omission is never silent.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS helpers
// ---------------------------------------------------------------------------

/**
 * Attempt to read a file that is expected to exist at `filePath`.
 *
 * Returns the Buffer on success, or null when:
 *   - the path is falsy / not provided
 *   - the file does not exist or is not readable
 *
 * Errors are surfaced as console warnings so operators always know why HTTPS
 * was not started.
 *
 * @param {string} filePath
 * @param {string} label     Human-readable label used in warning messages.
 * @returns {Buffer|null}
 */
function readFileOrWarn(filePath, label) {
  if (!filePath) {
    console.warn(`[config] ${label} is not set – skipping HTTPS.`);
    return null;
  }

  const resolved = path.resolve(filePath);

  try {
    return fs.readFileSync(resolved);
  } catch (err) {
    console.warn(
      `[config] Could not read ${label} at "${resolved}": ${err.message} – skipping HTTPS.`
    );
    return null;
  }
}

/**
 * Build the TLS options object expected by Node's `https.createServer()`.
 *
 * Returns `null` when valid cert + key material cannot be loaded, which
 * signals to callers that HTTPS should not be started.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 */
function loadTlsOptions() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  const cert = readFileOrWarn(certPath, 'TLS_CERT_PATH');
  if (!cert) return null;

  const key = readFileOrWarn(keyPath, 'TLS_KEY_PATH');
  if (!key) return null;

  return { cert, key };
}

// ---------------------------------------------------------------------------
// Exported configuration object
// ---------------------------------------------------------------------------
const tlsOptions = loadTlsOptions();

module.exports = {
  /** Port for the plain HTTP server (default: 3000). */
  HTTP_PORT,

  /** Port for the HTTPS server (default: 3443). */
  HTTPS_PORT,

  /**
   * TLS options ready to be passed to `https.createServer()`.
   * `null` means certificate material is unavailable; only HTTP will start.
   *
   * @type {{ cert: Buffer, key: Buffer }|null}
   */
  tlsOptions,

  /** Convenience boolean – true when HTTPS can be started. */
  httpsEnabled: tlsOptions !== null,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour:
 *   - Always starts an HTTP server on HTTP_PORT  (default 3000).
 *   - Starts an HTTPS server on HTTPS_PORT (default 3443) when TLS_CERT_PATH
 *     and TLS_KEY_PATH are set and the files are readable.
 *   - Falls back to HTTP-only with a clear console warning when cert material
 *     is missing or unreadable.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup  (skipped when the module is required by tests)
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  // -- HTTP ------------------------------------------------------------------
  http.createServer(app).listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // -- HTTPS (conditional) ---------------------------------------------------
  if (config.httpsEnabled) {
    https.createServer(config.tlsOptions, app).listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.warn(
      '[https] TLS certificates unavailable – running in HTTP-only mode. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }
}

module.exports = app;

