/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS certificate paths are read exclusively from the environment variables
 * TLS_CERT_PATH and TLS_KEY_PATH.  No other environment variables are read
 * or surfaced by this module.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ─── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = 3000;
const HTTPS_PORT = 3443;

// ─── TLS helpers ──────────────────────────────────────────────────────────────

/**
 * Resolve and validate a file path that came from an environment variable.
 * Returns the absolute path when the file is readable, or null otherwise.
 *
 * @param {string|undefined} envValue  Raw value of the environment variable.
 * @param {string}           varName   Variable name (used in log messages only).
 * @returns {string|null}
 */
function resolveFilePath(envValue, varName) {
  if (!envValue || !envValue.trim()) {
    return null;
  }

  const resolved = path.resolve(envValue.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch {
    console.warn(
      `[config] Warning: ${varName}="${envValue}" resolved to "${resolved}" ` +
      'but the file is not readable — HTTPS will be disabled.'
    );
    return null;
  }
}

/**
 * Build the TLS configuration object when both certificate paths are present
 * and point to readable files.
 *
 * @returns {{ certPath: string, keyPath: string }|null}
 */
function buildTlsConfig() {
  const certPath = resolveFilePath(process.env.TLS_CERT_PATH, 'TLS_CERT_PATH');
  const keyPath  = resolveFilePath(process.env.TLS_KEY_PATH,  'TLS_KEY_PATH');

  if (certPath && keyPath) {
    return { certPath, keyPath };
  }

  // Only warn when one variable is set but not the other (likely misconfiguration).
  if (certPath || keyPath) {
    console.warn(
      '[config] Warning: Both TLS_CERT_PATH and TLS_KEY_PATH must be set to ' +
      'enable HTTPS. Falling back to HTTP-only.'
    );
  }

  return null;
}

// ─── Exported configuration ───────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * TLS configuration derived from TLS_CERT_PATH and TLS_KEY_PATH.
   * null when HTTPS should not be started.
   *
   * Shape: { certPath: string, keyPath: string }
   */
  tls: buildTlsConfig(),
};

// app.js
//
// Starts an Express application on HTTP (port 3000) and, when TLS certificate
// paths are supplied via TLS_CERT_PATH / TLS_KEY_PATH environment variables,
// also on HTTPS (port 3443).  See config.js for configuration details.

'use strict';

const fs      = require('fs');
const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ─── HTTP server ──────────────────────────────────────────────────────────────

const httpServer = http.createServer(app);

httpServer.listen(config.HTTP_PORT, () => {
  console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
});

// ─── HTTPS server (only when certs are available) ─────────────────────────────

if (config.tls) {
  let tlsOptions;

  try {
    tlsOptions = {
      cert: fs.readFileSync(config.tls.certPath),
      key:  fs.readFileSync(config.tls.keyPath),
    };
  } catch (err) {
    // A file that was readable during config evaluation became unreadable
    // between startup and now (e.g. permissions changed mid-boot).
    console.error(
      `[https] Failed to read TLS files — falling back to HTTP-only.\n` +
      `        ${err.message}`
    );
    tlsOptions = null;
  }

  if (tlsOptions) {
    const httpsServer = https.createServer(tlsOptions, app);

    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  }
} else {
  console.log('[https] TLS not configured — running HTTP-only (set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS).');
}

module.exports = app;

