/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven entirely by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute or relative path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is absent the server starts in HTTP-only mode
 * without throwing an error.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS certificate loading
// ---------------------------------------------------------------------------

/**
 * Attempt to read a file and return its contents as a Buffer.
 * Returns null (and logs a warning) if the path is falsy or the file cannot
 * be read, so callers can degrade gracefully.
 *
 * @param {string} envVar  - Name of the environment variable (for logging).
 * @param {string} filePath - Value of the environment variable.
 * @returns {Buffer|null}
 */
function readCertFile(envVar, filePath) {
  if (!filePath) {
    // Variable not set – silent; caller decides what to do.
    return null;
  }

  const resolved = path.resolve(filePath);

  try {
    return fs.readFileSync(resolved);
  } catch (err) {
    console.warn(
      `[config] WARNING: ${envVar}="${filePath}" could not be read: ${err.message}`
    );
    return null;
  }
}

const certBuffer = readCertFile('TLS_CERT_PATH', process.env.TLS_CERT_PATH);
