/**
 * config.js
 *
 * Central configuration module. Reads TLS certificate paths from environment
 * variables and exposes a validated, ready-to-use config object.
 *
 * Environment variables
 * ---------------------
 *   TLS_CERT_PATH  – Absolute or relative path to the PEM-encoded certificate
 *                    file (and any intermediate chain).
 *   TLS_KEY_PATH   – Absolute or relative path to the PEM-encoded private key
 *                    file that corresponds to the certificate.
 *
 * TLS is considered "available" only when BOTH variables are set AND both
 * paths resolve to readable files on disk. If either condition is not met the
 * module logs a warning and the caller should fall back to HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS helpers ──────────────────────────────────────────────────────────────

/**
 * Resolve a raw path value (from an env var) to an absolute path string, or
 * return null when the value is missing / blank.
 *
 * @param {string|undefined} rawValue
 * @returns {string|null}
 */
function resolvePath(rawValue) {
  if (!rawValue || !rawValue.trim()) return null;
  return path.resolve(rawValue.trim());
}

/**
 * Return true when `filePath` exists and is readable by the current process.
 *
 * @param {string} filePath
 * @returns {boolean}
 */
function isReadable(filePath) {
  try {
    fs.accessSync(filePath, fs.constants.R_OK);
    return true;
  } catch {
    return false;
  }
}

/**
 * Attempt to load TLS credentials from the paths declared in the environment.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}  Credential buffers on success,
 *                                                null when TLS is unavailable.
 */
function loadTlsCredentials() {
  const certPath = resolvePath(process.env.TLS_CERT_PATH);
  const keyPath  = resolvePath(process.env.TLS_KEY_PATH);

  // Both variables must be present.
  if (!certPath || !keyPath) {
    if (certPath || keyPath) {
      // One is set but the other is missing — warn so the operator notices the
      // misconfiguration rather than silently falling back to HTTP.
      console.warn(
        '[config] WARNING: TLS is disabled — both TLS_CERT_PATH and ' +
        'TLS_KEY_PATH must be set. Only %s was provided.',
        certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH',
      );
    }
    return null;
  }

  // Both paths must point to readable files.
  if (!isReadable(certPath)) {
    console.warn('[config] WARNING: TLS is disabled — certificate file not readable: %s', certPath);
    return null;
  }
  if (!isReadable(keyPath)) {
    console.warn('[config] WARNING: TLS is disabled — key file not readable: %s', keyPath);
    return null;
  }

  try {
    const cert = fs.readFileSync(certPath);
    const key  = fs.readFileSync(keyPath);
    console.log('[config] TLS credentials loaded successfully.');
    return { cert, key };
  } catch (err) {
    console.warn('[config] WARNING: TLS is disabled — failed to read TLS files: %s', err.message);
    return null;
  }
}

// ── Exported config ──────────────────────────────────────────────────────────

const tlsCredentials = loadTlsCredentials();

module.exports = {
  /** Port the HTTP server will listen on. */
  HTTP_PORT,

  /** Port the HTTPS server will listen on (only used when TLS is available). */
  HTTPS_PORT,

  /**
   * TLS credentials object `{ cert, key }` when both env vars are set and both
   * files are readable, otherwise `null`.  The consuming module should use this
   * value to decide whether to start an HTTPS server.
   */
  tlsCredentials,

  /** Convenience boolean — true when HTTPS can be started. */
  tlsAvailable: tlsCredentials !== null,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ---------
 *   • HTTP server always starts on HTTP_PORT (default 3000).
 *   • HTTPS server starts on HTTPS_PORT (default 3443) only when valid TLS
 *     credentials are discovered by the config module.  If certs are absent or
 *     unreadable the process continues in HTTP-only mode with a warning.
 *
 * TLS configuration
 * -----------------
 *   Set the following environment variables before starting the process:
 *
 *     TLS_CERT_PATH=/path/to/server.crt   # PEM certificate (+ chain)
 *     TLS_KEY_PATH=/path/to/server.key    # PEM private key
 *
 *   Optional port overrides:
 *
 *     HTTP_PORT=3000    # (default)
 *     HTTPS_PORT=3443   # (default)
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start both servers and return them so callers (e.g. tests) can shut them
 * down cleanly with server.close().
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // Always start HTTP.
  const httpServer = http.createServer(app);

  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[server] HTTP  listening on http://localhost:${config.HTTP_PORT}`);
