// config.js
// Centralises runtime configuration. TLS certificate paths are read from
// environment variables so that no secrets are hard-coded in source.

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS configuration
// ---------------------------------------------------------------------------
// Paths to the PEM-encoded certificate and private key are supplied through
// the environment so they never need to be committed to the repository.
//
//   TLS_CERT_PATH  – path to the TLS certificate (or full-chain) file
//   TLS_KEY_PATH   – path to the private key file
//
// Both variables must be set AND both files must be readable for HTTPS to be
// enabled.  If either is missing the server falls back to HTTP-only mode and
// logs a clear reason.

function loadTlsConfig() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // 1. Check that both env vars are present.
  if (!certPath && !keyPath) {
    return {
      enabled: false,
      reason: 'TLS_CERT_PATH and TLS_KEY_PATH are not set',
    };
  }
  if (!certPath) {
    return { enabled: false, reason: 'TLS_CERT_PATH is not set' };
  }
  if (!keyPath) {
    return { enabled: false, reason: 'TLS_KEY_PATH is not set' };
  }

  // 2. Resolve to absolute paths so error messages are unambiguous.
  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // 3. Verify the files actually exist and are readable before handing the
  //    paths back, so the server fails fast with a clear message instead of
  //    crashing deep inside the TLS handshake.
  try {
    fs.accessSync(resolvedCert, fs.constants.R_OK);
  } catch {
    return {
      enabled: false,
      reason: `TLS certificate file is not readable: ${resolvedCert}`,
    };
  }

  try {
    fs.accessSync(resolvedKey, fs.constants.R_OK);
  } catch {
    return {
      enabled: false,
      reason: `TLS key file is not readable: ${resolvedKey}`,
    };
  }

  return {
    enabled:  true,
    certPath: resolvedCert,
    keyPath:  resolvedKey,
  };
}

const tls = loadTlsConfig();

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  tls,
};

// app.js
// Express application with optional HTTPS support.
// HTTP is always started (port 3000 by default).
// HTTPS is started on port 3443 when TLS_CERT_PATH and TLS_KEY_PATH are set
// and both files are readable; otherwise the server falls back to HTTP-only.

'use strict';

const fs      = require('fs');
const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

function startServers() {
