/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is controlled entirely by two environment variables:
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is missing the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Resolves a raw path string from an environment variable to an absolute path,
 * or returns null when the variable is not set.
 *
 * @param {string|undefined} rawPath
 * @returns {string|null}
 */
function resolveCertPath(rawPath) {
  if (!rawPath || !rawPath.trim()) return null;
  return path.isAbsolute(rawPath) ? rawPath : path.resolve(process.cwd(), rawPath);
}

/**
 * Attempts to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * Returns an object with `cert` and `key` Buffer properties when both files
 * are present and readable, or `null` if HTTPS should be skipped.
 *
 * Errors are surfaced as thrown exceptions so the caller can decide whether to
 * abort or fall back to HTTP-only mode.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 */
function loadTlsCredentials() {
  const certPath = resolveCertPath(process.env.TLS_CERT_PATH);
  const keyPath  = resolveCertPath(process.env.TLS_KEY_PATH);

  // Neither variable set → caller should use HTTP-only mode.
  if (!certPath && !keyPath) return null;

  // Only one variable set → likely a misconfiguration; warn and skip HTTPS.
  if (!certPath || !keyPath) {
    const missing = !certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH';
    console.warn(
      `[config] WARNING: ${missing} is not set. ` +
      'Both TLS_CERT_PATH and TLS_KEY_PATH are required to enable HTTPS. ' +
      'Falling back to HTTP-only mode.'
    );
    return null;
  }

  // Both variables set → try to read the files.
  let cert, key;
  try {
    cert = fs.readFileSync(certPath);
  } catch (err) {
    throw new Error(
      `[config] Cannot read TLS certificate at "${certPath}": ${err.message}`
    );
  }
  try {
    key = fs.readFileSync(keyPath);
  } catch (err) {
    throw new Error(
      `[config] Cannot read TLS private key at "${keyPath}": ${err.message}`
    );
  }

  return { cert, key };
}

