/**
 * config.js
 *
 * Central configuration module. TLS settings are read exclusively from
 * environment variables so that no secrets are ever hard-coded.
 *
 * Expected environment variables (both required to enable HTTPS):
 *   TLS_CERT_PATH  – absolute or relative path to the PEM-encoded certificate
 *   TLS_KEY_PATH   – absolute or relative path to the PEM-encoded private key
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ──────────────────────────────────────────────────────────────────────

/**
 * Resolve a file path and return its contents, or null if anything goes wrong.
 * Errors are logged with enough context to be actionable without leaking data.
 *
 * @param {string} envVar  Name of the environment variable holding the path.
 * @returns {Buffer|null}
 */
function readCertFile(envVar) {
  const filePath = process.env[envVar];

  if (!filePath) {
    return null; // variable not set – not an error
  }

  const resolved = path.resolve(filePath);

  try {
    return fs.readFileSync(resolved);
  } catch (err) {
    // Surface a clear, actionable message without echoing the file contents.
    console.error(
      `[config] Cannot read TLS file for ${envVar} at "${resolved}": ${err.message}`
    );
    return null;
  }
}

/**
 * Build and validate the TLS configuration object.
 *
 * Both TLS_CERT_PATH and TLS_KEY_PATH must be set **and** their files must be
 * readable for HTTPS to be enabled.  If either is missing or unreadable the
 * function returns null and the caller should fall back to HTTP-only mode.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 */
function buildTlsConfig() {
  const cert = readCertFile('TLS_CERT_PATH');
  const key  = readCertFile('TLS_KEY_PATH');

  if (cert && key) {
    return { cert, key };
  }

  // Emit a single, consolidated warning so operators know why HTTPS is off.
  if (cert || key) {
    // One variable is set but the other is missing.
    const missing = cert ? 'TLS_KEY_PATH' : 'TLS_CERT_PATH';
    console.warn(
      `[config] HTTPS disabled: ${missing} is not set or its file could not be read.`
    );
  }
  // If neither is set we stay silent – HTTP-only is an expected configuration.

  return null;
}

// ── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * TLS options object ({ cert, key }) ready to pass directly to
   * https.createServer(), or null when HTTPS should not be started.
   *
   * Evaluated once at require() time so every module that imports this config
   * sees a consistent snapshot for the lifetime of the process.
   */
  tlsConfig: buildTlsConfig(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Ports and TLS certificate paths are controlled entirely through environment
 * variables – see config.js for the full list.
 *
 * Behaviour:
 *   • TLS_CERT_PATH + TLS_KEY_PATH set and files readable
 *       → HTTP  on HTTP_PORT  (default 3000)
 *       → HTTPS on HTTPS_PORT (default 3443)
 *   • Either variable missing or file unreadable
 *       → HTTP only on HTTP_PORT (default 3000)
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ───────────────────────────────────────────────────────────

/**
 * Start the HTTP and (optionally) HTTPS servers.
 *
 * Separating this into a named function makes it straightforward to call from
 * tests without binding to real ports during unit-test runs.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // HTTP – always started
  const httpServer = http.createServer(app);

  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // HTTPS – only when a valid TLS configuration is available
  let httpsServer = null;

  if (config.tlsConfig) {
    httpsServer = https.createServer(config.tlsConfig, app);

    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.warn(
      '[https] TLS configuration unavailable – running in HTTP-only mode. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return { httpServer, httpsServer };
}

// Start the servers only when this file is run directly (not when imported
// by tests or other modules), mirroring the standard Node.js convention.
if (require.main === module) {
  startServers();
}

// ── Exports ──────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

