// config.js — centralised application configuration
// TLS certificate paths are read exclusively from environment variables so that
// no secrets or file-system paths are ever hard-coded in source.

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Helper – resolve and validate a file path from an env variable.
// Returns the resolved absolute path when the file exists, or null otherwise.
// ---------------------------------------------------------------------------
function resolveFilePath(envVar) {
  const raw = process.env[envVar];
  if (!raw || raw.trim() === '') {
    return null;
  }

  const resolved = path.resolve(raw.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch {
    // File does not exist or is not readable – warn and fall back to HTTP-only.
    console.warn(
      `[config] WARNING: ${envVar}="${raw}" is set but the file ` +
        `"${resolved}" is not readable. HTTPS will be disabled.`
    );
    return null;
  }
}

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS – both variables must point to readable files for HTTPS to be enabled.
// ---------------------------------------------------------------------------
const certPath = resolveFilePath('TLS_CERT_PATH');
const keyPath  = resolveFilePath('TLS_KEY_PATH');

const tlsEnabled = certPath !== null && keyPath !== null;

if (!tlsEnabled) {
  if (!certPath && process.env.TLS_CERT_PATH) {
    // Warning already emitted by resolveFilePath; nothing extra needed.
  } else if (!certPath) {
    console.info('[config] TLS_CERT_PATH is not set. Running HTTP-only.');
  }
}

// ---------------------------------------------------------------------------
// Exported configuration object (read-only via Object.freeze)
// ---------------------------------------------------------------------------
const config = Object.freeze({
  /** TCP port for the plain-text HTTP server. */
  httpPort: HTTP_PORT,

  /** TCP port for the TLS-encrypted HTTPS server. */
  httpsPort: HTTPS_PORT,

  /**
   * Whether HTTPS should be started.
   * True only when both TLS_CERT_PATH and TLS_KEY_PATH resolve to readable
   * files on disk.
   */
  tlsEnabled,

  /**
   * Absolute path to the PEM-encoded TLS certificate (or certificate chain).
   * Null when tlsEnabled is false.
   */
  tlsCertPath: certPath,

  /**
   * Absolute path to the PEM-encoded private key that matches the certificate.
   * Null when tlsEnabled is false.
   */
  tlsKeyPath: keyPath,
});

module.exports = config;

// app.js — Express application with HTTP + optional HTTPS support.
// HTTPS is enabled automatically when TLS_CERT_PATH and TLS_KEY_PATH
// environment variables point to readable PEM files (see config.js).

'use strict';

const fs      = require('fs');
const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

/**
 * Start the HTTP server on config.httpPort.
 * Always started regardless of TLS availability.
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(config.httpPort, () => {
    console.log(`[http]  Server listening on http://localhost:${config.httpPort}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server on port ${config.httpPort}:`, err.message);
    process.exit(1);
  });

  return server;
}

/**
 * Start the HTTPS server on config.httpsPort.
 * Only called when config.tlsEnabled is true.
 *
 * The certificate and key are read from disk at startup so that any I/O
 * errors surface immediately with a clear message rather than at the first
 * incoming TLS handshake.
 */
function startHttps() {
  let tlsOptions;

  try {
    tlsOptions = {
      cert: fs.readFileSync(config.tlsCertPath),
      key:  fs.readFileSync(config.tlsKeyPath),
    };
  } catch (err) {
    console.error('[https] Failed to read TLS certificate/key files:', err.message);
    console.warn( '[https] Falling back to HTTP-only mode.');
    return null;
  }

  const server = https.createServer(tlsOptions, app);

  server.listen(config.httpsPort, () => {
    console.log(`[https] Server listening on https://localhost:${config.httpsPort}`);
  });

  server.on('error', (err) => {
    console.error(`[https] Failed to start HTTPS server on port ${config.httpsPort}:`, err.message);
    // HTTPS failure is non-fatal: HTTP server continues running.
  });

  return server;
}

// Start HTTP (always).
const httpServer = startHttp();

// Start HTTPS only when both cert and key paths are configured and readable.
const httpsServer = config.tlsEnabled ? startHttps() : null;

if (!config.tlsEnabled) {
  console.info('[app]   HTTPS is disabled. Set TLS_CERT_PATH and TLS_KEY_PATH to enable it.');
}

// ---------------------------------------------------------------------------
// Exports – expose the app and both server instances for testing.
// ---------------------------------------------------------------------------

module.exports = { app, httpServer, httpsServer };

